previewCss:
.darma-loader-darma-b16-litmus-strip { --accent: var(--loader-color, #dc2626); --accent-2: var(--loader-secondary-color, #22c55e); width: calc(var(--loader-size, 110px) * .8); height: var(--loader-size, 110px); position: relative; }
.darma-loader-darma-b16-litmus-strip .darma-loader-darma-b16-litmus-strip__strip { position: absolute; left: 40%; top: 2%; width: 20%; height: 62%; border-radius: 3px; overflow: hidden; background: color-mix(in srgb, #fff 82%, var(--accent-2)); box-shadow: inset 0 0 0 1px color-mix(in srgb, #000 18%, transparent); animation: darma-loader-darma-b16-litmus-strip-litmus-dip calc(var(--loader-speed, 1s) * 3) ease-in-out infinite; }
.darma-loader-darma-b16-litmus-strip .darma-loader-darma-b16-litmus-strip__wick { position: absolute; left: 0; right: 0; bottom: 0; height: 0; background: linear-gradient(var(--accent), var(--accent-2)); animation: darma-loader-darma-b16-litmus-strip-litmus-wick calc(var(--loader-speed, 1s) * 3) ease-out infinite; }
.darma-loader-darma-b16-litmus-strip .darma-loader-darma-b16-litmus-strip__beaker { position: absolute; left: 16%; right: 16%; bottom: 2%; height: 34%; border-radius: 2px 2px 8px 8px; overflow: hidden; box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--accent-2) 45%, transparent); }
.darma-loader-darma-b16-litmus-strip .darma-loader-darma-b16-litmus-strip__fluid { position: absolute; left: 0; right: 0; bottom: 0; height: 62%; background: color-mix(in srgb, var(--accent-2) 40%, transparent); }
@keyframes darma-loader-darma-b16-litmus-strip-litmus-dip { 0%, 100% { transform: translateY(0); } 30%, 74% { transform: translateY(16%); } }
@keyframes darma-loader-darma-b16-litmus-strip-litmus-wick { 0%, 26% { height: 0; } 62%, 80% { height: 84%; } 96%, 100% { height: 0; } }

